#requires -Version 7.0
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
function Read-Run([string]$file,[string]$label){
 $path=Join-Path $root ('outputs/'+$file+'.json');if(!(Test-Path -LiteralPath $path)){return $null}
 $r=Get-Content $path -Raw|ConvertFrom-Json;$f=$r.Samples[0];$last=$r.Samples[-1];$cpu=($last.CpuSeconds-$f.CpuSeconds)/($last.Seconds-$f.Seconds)
 $latencies=@($r.Responses|Where-Object Command -eq save|ForEach-Object ElapsedMilliseconds|Where-Object {$_ -ne $null}|Sort-Object);$median=if($latencies.Count){$latencies[[int][math]::Floor($latencies.Count/2)]}else{$null}
 [pscustomobject]@{Workload=$label;File=$file;PeakResidentMiB=[math]::Round(($r.Samples.PeakResidentMiB|Measure-Object -Maximum).Maximum,2);PeakPrivateCommitMiB=[math]::Round(($r.Samples.PrivateCommitMiB|Measure-Object -Maximum).Maximum,2);AverageCpuCores=[math]::Round($cpu,3);AverageCpuPercentOfMachine=[math]::Round(100*$cpu/[int]$env:NUMBER_OF_PROCESSORS,2);SaveMedianMs=if($median){[math]::Round($median,2)}else{$null};SavedClips=$r.Clips.Count;Under50MiB=(($r.Samples.PeakResidentMiB|Measure-Object -Maximum).Maximum -lt 50);TestedBinarySha256=$r.TestedBinarySha256}
}
$comparison=@((Read-Run 'desktop-comparison-old' 'Previous build'),(Read-Run 'desktop-comparison-candidate-v2' 'Optimized profiling build'))|Where-Object {$_}
$other=@((Read-Run 'desktop-comparison-final' 'Final installed build: uncontrolled workload, game process present'),(Read-Run 'native-daemon-shipping' 'Earlier quiet desktop'),(Read-Run 'overwatch-active-capture' 'Previous build: Overwatch asset-load scene'),(Read-Run 'minimum-overhead-v2-ten-restarts' 'Optimized profiling build: ten restarts with GPU counters'),(Read-Run 'minimum-overhead-final-long' 'Optimized profiling build: 120 seconds'))|Where-Object {$_}
$lines=[Collections.Generic.List[string]]::new();$lines.Add('# ZenithClipper benchmarks');$lines.Add('');$lines.Add('Updated: '+[DateTimeOffset]::Now.ToString('o'))
$hardwarePath=Join-Path $root 'outputs/benchmark-hardware.json';if(Test-Path -LiteralPath $hardwarePath){$h=Get-Content $hardwarePath -Raw|ConvertFrom-Json;$lines.Add('');$lines.Add('Machine: '+$h.Processors[0].Name.Trim()+'; '+$h.InstalledRamGiB+' GiB RAM; '+(($h.Graphics.Name) -join ' + ')+'.');$lines.Add('GPU driver versions: '+(($h.Graphics|ForEach-Object {$_.Name+' '+$_.DriverVersion}) -join '; ')+'.')}
$lines.Add('');$lines.Add('## Same-settings desktop comparison');$lines.Add('');$lines.Add('Back-to-back comparison of the original build and the optimized profiling build before the live-save correctness fix. One isolated recorder process includes capture, encoding, app-audio selection, IPC and registered shortcuts. Each run starts fresh, records, saves and pauses three times. Native 2560x1600, 165 FPS encoded cadence, QP20, stereo 48 kHz AAC at 192 kbps. No quality reduction or working-set trimming. The source desktop was not a deterministic game benchmark.');$lines.Add('');$lines.Add('| Build | Peak resident RAM (MiB) | Peak private commit (MiB) | Average CPU (% of machine) | Median save response (ms) | Clips decoded | Below 50 MiB |');$lines.Add('| --- | ---: | ---: | ---: | ---: | ---: | --- |')
foreach($r in $comparison){$lines.Add('| '+$r.Workload+' | '+$r.PeakResidentMiB+' | '+$r.PeakPrivateCommitMiB+' | '+$r.AverageCpuPercentOfMachine+' | '+$r.SaveMedianMs+' | '+$r.SavedClips+' | '+$(if($r.Under50MiB){'Yes'}else{'No'})+' |')}
if($comparison.Count -eq 2){$before=$comparison[0];$after=$comparison[1];$lines.Add('');$lines.Add(('Observed reductions: {0:F1}% peak resident RAM, {1:F1}% peak private commit, {2:F1}% average process CPU.' -f (100*(1-$after.PeakResidentMiB/$before.PeakResidentMiB)),(100*(1-$after.PeakPrivateCommitMiB/$before.PeakPrivateCommitMiB)),(100*(1-$after.AverageCpuCores/$before.AverageCpuCores))))}
$lines.Add("Desktop content and scheduling vary; small overall CPU differences are not statistically established.");
$installed=Get-FileHash -LiteralPath (Join-Path $root 'build/windows/ZenithClipper.Recorder.exe');$candidate=Read-Run 'desktop-comparison-final' 'Final installed build';$lines.Add('');$lines.Add($(if($candidate -and $candidate.TestedBinarySha256 -eq $installed.Hash){'The optimized executable matches the installed package.'}else{'The optimized executable is staged; installation is pending final verification.'}))
$lines.Add('');$lines.Add("Final installed save behavior differs from both profiling builds: it waits for a prompt keyframe/audio checkpoint covering the shortcut moment. The profiling builds could stop at an older completed fragment, omitting up to two seconds. Their faster save response is not equivalent correctness. Final installed median response was211ms.");$lines.Add("");$lines.Add('## Other workloads');$lines.Add('');$lines.Add('| Workload | Peak resident RAM (MiB) | Peak private commit (MiB) | Average CPU (% of machine) |');$lines.Add('| --- | ---: | ---: | ---: |');foreach($r in $other){$lines.Add('| '+$r.Workload+' | '+$r.PeakResidentMiB+' | '+$r.PeakPrivateCommitMiB+' | '+$r.AverageCpuPercentOfMachine+' |')}
$lines.Add('');$lines.Add('The earlier quiet desktop result is not a substitute for active-game testing. The Overwatch custom mode ran in the background; no game controls or foreground change were sent. All three saved clips decoded; one had 330 decoded frames and 319 distinct reduced-frame hashes. This does not prove 165 fresh game frames per second or zero FPS loss. A new Overwatch process started at20:09 before the final installed-build test at20:17; that final workload was uncontrolled and is not an apples-to-apples desktop or intentional game benchmark. The newer game process was left untouched. No controlled optimized game/frame-time test has been performed.')
$gpuPath=Join-Path $root 'outputs/minimum-overhead-v2-ten-restarts.json';if(Test-Path -LiteralPath $gpuPath){$g=Get-Content $gpuPath -Raw|ConvertFrom-Json;if($g.GpuSamples.Count){$dedicated=($g.GpuSamples|ForEach-Object {($_.Memory.DedicatedUsage|Measure-Object -Sum).Sum/1MB}|Measure-Object -Maximum).Maximum;$shared=($g.GpuSamples|ForEach-Object {($_.Memory.SharedUsage|Measure-Object -Sum).Sum/1MB}|Measure-Object -Maximum).Maximum;$lines.Add('');$lines.Add('## GPU measurements: optimized ten-restart run');$lines.Add('');$lines.Add(('Windows per-process counters, sampled about every two seconds: peak reported Dedicated Usage {0:F2} MiB; peak reported Shared Usage {1:F2} MiB. Dedicated Usage is not a validated physical-allocation figure: a separate restart test showed this counter rising while Local Usage and Total Committed stayed constant. GPU counters are separate from resident CPU RAM.' -f $dedicated,$shared));$lines.Add('');$lines.Add('| GPU engine | Peak sampled utilization |');$lines.Add('| --- | ---: |');foreach($type in @('3D','VideoEncode','Copy')){$samples=@($g.GpuSamples.Engines|Where-Object {($_.Name -split '_engtype_')[-1] -eq $type});$value=($samples.UtilizationPercentage|Measure-Object -Maximum).Maximum;$lines.Add('| '+$type+' | '+$value+'% |')};$lines.Add('');$lines.Add('VideoEncode is the dedicated encoder engine, not overall GPU or game 3D utilization. These sampled peaks can miss shorter spikes. Save-latency results from this instrumented run are excluded because counter collection can delay the test client.')}}
$lines.Add('');$precisePath=Join-Path $root 'outputs/minimum-overhead-final-long.json';if(Test-Path -LiteralPath $precisePath){$precise=Get-Content $precisePath -Raw|ConvertFrom-Json;if($precise.GpuSamples.Count){$local=($precise.GpuSamples|ForEach-Object {($_.Memory.LocalUsage|Measure-Object -Sum).Sum/1MB}|Measure-Object -Maximum).Maximum;$nonlocal=($precise.GpuSamples|ForEach-Object {($_.Memory.NonLocalUsage|Measure-Object -Sum).Sum/1MB}|Measure-Object -Maximum).Maximum;$committed=($precise.GpuSamples|ForEach-Object {($_.Memory.TotalCommitted|Measure-Object -Sum).Sum/1MB}|Measure-Object -Maximum).Maximum;$lines.Add(('Extended-run counter cross-check: Local Usage {0:F2} MiB; NonLocal Usage {1:F2} MiB; Total Committed {2:F2} MiB. These are different GPU accounting measures, not values to add to one another.' -f $local,$nonlocal,$committed));$lines.Add('')}}
$lines.Add('## Isolated replay bookkeeping');$lines.Add('');$lines.Add('| Measurement | Before | After |');$lines.Add('| --- | ---: | ---: |');$lines.Add('| CPU: 12,000 video + 3,409 AAC packets and 12,000 metrics polls | 6,765.62 ms | 234.38 ms |');$lines.Add('| Managed allocation | 26,413,208 B | 1,064,056 B |');$lines.Add('| Repeated oldest-index reader opens | 42,818 | 0 |');$lines.Add('');$lines.Add('Tiny synthetic payloads isolate bookkeeping; this is not an overall capture/GPU speedup. The one-record cache adds 64 bytes. Full quick Media regressions passed.')
$lines.Add('');$lines.Add('## Limits and evidence');$lines.Add('');$lines.Add('- Below-50-MiB total resident usage has not been achieved. No universal maximum or zero game-FPS-loss guarantee is claimed.');$lines.Add('- MiB = 1,048,576 bytes. Resident RAM includes shared executable/library pages; private commit is a separate allocation measure. GPU memory and on-demand UI/editor memory are separate.');$lines.Add('- CPU uses process CPU time divided by test wall time and '+$env:NUMBER_OF_PROCESSORS+' logical processors; it includes startup, saves and pauses.');$lines.Add('- Game frame-time impact, optimized active-game performance, competitors, Linux and other machines remain unmeasured.');$lines.Add('- Rejected fence-event synchronization experiments hung in stress tests and are not in the product. Original GPU synchronization and pacing are retained.');$lines.Add('- Raw measurements: outputs/desktop-comparison-old.json, outputs/desktop-comparison-candidate-v2.json, outputs/desktop-comparison-final.json, outputs/minimum-overhead-v2-ten-restarts.json and outputs/overwatch-active-capture.json. Native bridge and audio tests: tests/NativeVideoComponent/wgc-bridge-validation.md.');$lines.Add('- The original game test threshold mistakenly depended on duration. Its raw counters were retained, its result corrected to fail, and the harness now uses an independent explicit memory budget.')
$lines.Add('');$lines.Add('Launch with Launch ZenithClipper.cmd. Alt+C saves; Shift+~ (same physical key as Shift+`) opens the menu. Both shortcuts are configurable. Benchmarking leaves capture off.')
$lines|Set-Content -LiteralPath (Join-Path $root 'BENCHMARKS.md');@($comparison)+@($other)|Export-Csv -LiteralPath (Join-Path $root 'BENCHMARKS.csv') -NoTypeInformation
foreach($file in @('BENCHMARKS.md','BENCHMARKS.csv')){Copy-Item -LiteralPath (Join-Path $root $file) -Destination (Join-Path $root 'build/windows') -Force}
$comparison|Format-Table -AutoSize




